+
+    button:hover {
+      filter: brightness(1.05);
+      transform: translateY(-1px);
+    }
+
+    button:focus {
+      outline: none;
+      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.22), 0 14px 30px rgba(95, 125, 255, 0.25);
+    }
+
+    .status {
+      margin-top: 16px;
+      color: #b9c4dd;
+      font-size: 0.95rem;
+      min-height: 1.2em;
