  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2f;
      --panel-2: #17213a;
      --border: #27324d;
      --text: #e8edf8;
      --muted: #9aa7c2;
      --accent: #7c9cff;
      --accent-strong: #9bb2ff;
      --danger: #ff7a90;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.2), transparent 30%),
        linear-gradient(180deg, #08101f 0%, #0b1020 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .contact-card {
      width: min(100%, 620px);
      background: linear-gradient(180deg, rgba(18, 26, 47, 0.98), rgba(11, 16, 32, 0.98));
      border: 1px solid rgba(124, 156, 255, 0.16);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent-strong);
      text-transform: uppercase;
      letter-spacing: 0.16em;
      font-size: 0.78rem;
      font-weight: 700;
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 0 0 28px;
      color: var(--muted);
      max-width: 52ch;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      font-size: 0.96rem;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      background: var(--panel-2);
      color: var(--text);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #7382a4;
    }

    input:focus {
      outline: none;
      border-color: rgba(124, 156, 255, 0.9);
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.16);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.9rem;
      margin-top: -2px;
    }

    .error-message {
      color: var(--danger);
      font-size: 0.9rem;
      min-height: 1.1em;
    }

    .form-field.invalid input {
      border-color: rgba(255, 122, 144, 0.9);
      box-shadow: 0 0 0 4px rgba(255, 122, 144, 0.12);
    }

    .actions {
      margin-top: 8px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 14px;
      padding: 14px 20px;
      background: linear-gradient(135deg, var(--accent), #5f7dff);
      color: white;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(95, 125, 255, 0.25);
      transition: transform 0.2s ease, filter 0.2s ease;
    }

    button:hover {
      filter: brightness(1.05);
      transform: translateY(-1px);
    }

    button:focus {
      outline: none;
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.22), 0 14px 30px rgba(95, 125, 255, 0.25);
    }

    .status {
      margin-top: 16px;
      color: #b9c4dd;
      font-size: 0.95rem;
      min-height: 1.2em;
    }
  </style>
</head>
<body>
  <main class="contact-card">
    <p class="eyebrow">Support</p>
    <h1>Contact our team</h1>
    <p class="subtitle">Send a quick message and we’ll get back to you as soon as possible.</p>

    <form id="contact-form" novalidate>
      <div class="form-field">
        <label for="fullName">Full name</label>
        <input id="fullName" name="fullName" type="text" autocomplete="name" required placeholder="Jane Doe" />
        <div class="error-message" id="fullNameError" aria-live="polite" hidden></div>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" required placeholder="jane@example.com" />
        <div class="error-message" id="emailError" aria-live="polite" hidden></div>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="+1 555 123 4567" />
        <div class="helper-text">Use digits with optional spaces, dashes, or a leading +, such as +1 555 123 4567.</div>
        <div class="error-message" id="phoneError" aria-live="polite" hidden></div>
      </div>

      <div class="actions">
        <button type="submit">Send message</button>
      </div>

      <div class="status" id="formStatus" aria-live="polite"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('contact-form');
    const fullName = document.getElementById('fullName');
    const email = document.getElementById('email');
    const phone = document.getElementById('phone');
    const formStatus = document.getElementById('formStatus');

    const fields = {
      fullName: {
        input: fullName,
        error: document.getElementById('fullNameError'),
        validate: () => fullName.value.trim() ? '' : 'Full name is required.'
      },
      email: {
        input: email,
        error: document.getElementById('emailError'),
        validate: () => {
          if (!email.value.trim()) return 'Email address is required.';
          return email.validity.valid ? '' : 'Enter a valid email address.';
        }
      },
      phone: {
        input: phone,
        error: document.getElementById('phoneError'),
        validate: () => {
          const value = phone.value.trim();
          if (!value) return '';
          return /^[+]?[\d\s()-]{7,}$/.test(value) ? '' : 'Enter a valid phone number format.';
        }
      }
    };

    function setFieldState(field, message) {
      const fieldWrapper = field.input.closest('.form-field');
      if (message) {
        fieldWrapper.classList.add('invalid');
        field.error.textContent = message;
        field.error.hidden = false;
      } else {
        fieldWrapper.classList.remove('invalid');
        field.error.textContent = '';
        field.error.hidden = true;
      }
    }

    function validateForm() {
      const errors = Object.values(fields).map((field) => {
        const message = field.validate();
        setFieldState(field, message);
        return message;
      });

      return errors.every((message) => !message);
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      formStatus.textContent = '';

      if (!validateForm()) {
        formStatus.textContent = 'Please fix the highlighted fields and try again.';
        return;
      }

      formStatus.textContent = 'Thanks — your message has been prepared for sending.';
      form.reset();
      Object.values(fields).forEach((field) => setFieldState(field, ''));
    });

    [fullName, email, phone].forEach((input) => {
      input.addEventListener('input', () => {
        const field = Object.values(fields).find((candidate) => candidate.input === input);
        const message = field.validate();
        if (!field.error.hidden || input.closest('.form-field').classList.contains('invalid')) {
          setFieldState(field, message);
        }
      });
    });
  </script>
</body>
</html>
